func TestNovelJSONFileHashStable(t *testing.T) {
	a := novelJSONFileHash([]byte(`[]`))
	b := novelJSONFileHash([]byte(`[]`))
	c := novelJSONFileHash([]byte(`[{}]`))
	if a == "" || a != b || a == c {
		t.Fatalf("hash stability failed: a=%q b=%q c=%q", a, b, c)
	}
}

func TestNovelMirrorWritesPrivateFilesAndRefusesOverwrite(t *testing.T) {
	seedNovelCommandStore(t)
	// mirror creates a missing export dir as 0700 ...
	exportDir := filepath.Join(t.TempDir(), "mirror-out")

	runNovelCommand(t, "mirror", "--export-dir", exportDir, "--verify")
	if info, err := os.Stat(exportDir); err != nil {
		t.Fatal(err)
	} else if got := info.Mode().Perm(); got != 0o700 {
		t.Fatalf("export dir mode = %#o, want 0700", got)
	}
	// ... but never chmods a directory it did not create (security review row 21).
	preexisting := t.TempDir()
	if err := os.Chmod(preexisting, 0o755); err != nil {
		t.Fatal(err)
	}
	runNovelCommand(t, "mirror", "--export-dir", preexisting, "--verify")
	if info, err := os.Stat(preexisting); err != nil {
		t.Fatal(err)
	} else if got := info.Mode().Perm(); got != 0o755 {
		t.Fatalf("pre-existing export dir mode changed to %#o, want 0755 untouched", got)
	}
	for _, name := range []string{"books.json", "documents.json", "highlights.json", "tags.json", "manifest.json"} {
		info, err := os.Stat(filepath.Join(exportDir, name))
		if err != nil {
			t.Fatalf("stat %s: %v", name, err)
		}
		if got := info.Mode().Perm(); got != 0o600 {
			t.Fatalf("%s mode = %#o, want 0600", name, got)
		}
	}

	var flags rootFlags
	cmd := newRootCmd(&flags)
	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(io.Discard)
	cmd.SetArgs([]string{"--json", "mirror", "--export-dir", exportDir})
	err := cmd.Execute()
	if err == nil {
		t.Fatalf("second mirror without --force succeeded, want overwrite refusal")
	}
	if !strings.Contains(err.Error(), "books.json") || !strings.Contains(err.Error(), "--force") {
		t.Fatalf("overwrite error = %v, want existing file names and --force hint", err)
	}
}

func TestE3MirrorSafeReplacement(t *testing.T) {
	seedNovelCommandStore(t)
	dir := t.TempDir()
	if err := os.Chmod(dir, 0755); err != nil {
		t.Fatal(err)
	}
	victim := filepath.Join(t.TempDir(), "victim.json")
	if err := os.WriteFile(victim, []byte("foreign fixture"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(victim, filepath.Join(dir, "books.json")); err != nil {
		t.Fatal(err)
	}
	runNovelCommand(t, "mirror", "--export-dir", dir, "--force")
	raw, _ := os.ReadFile(victim)
	info, _ := os.Stat(victim)
	dirInfo, _ := os.Stat(dir)
	if string(raw) != "foreign fixture" || info.Mode().Perm() != 0644 || dirInfo.Mode().Perm() != 0755 {
		t.Fatalf("modified existing destination: %s file=%v dir=%v", raw, info.Mode(), dirInfo.Mode())
	}
	replaced, err := os.Lstat(filepath.Join(dir, "books.json"))
	if err != nil || replaced.Mode()&os.ModeSymlink != 0 || replaced.Mode().Perm() != 0600 {
		t.Fatalf("replacement: %v %v", replaced, err)
	}
	cmd := newNovelMirrorCmd(&rootFlags{})
	if cmd.Annotations["mcp:write-flags"] != "export-dir" {
		t.Fatal("export directory must be classified as MCP write destination")
	}
}
